import React,{useState} from "react";
import api from "../services/api";

export default function ShareCapital(){
  const [id,setId]=useState("3"),[data,setData]=useState(null);
  const load=async e=>{e.preventDefault();try{setData((await api.get(`/share-capital/${id}`)).data)}catch{setData(null)}};
  return <>
    <div className="page-head"><div><span className="eyebrow">COOPERATIVE EQUITY</span><h2>Share Capital</h2><p>Check a member's share capital balance.</p></div></div>
    <form className="inline-form" onSubmit={load}><input value={id} onChange={e=>setId(e.target.value)} placeholder="Member ID"/><button className="primary">Check balance</button></form>
    {data&&<div className="capital-card"><div className="capital-icon">₹</div><div><span>{data.memberId}</span><h3>{data.memberName}</h3><p>Current share capital</p></div><strong>₹{data.shareCapital}</strong></div>}
  </>;
}
